function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  for var i := 0 to numbers.Length - 2 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var current := '';
  var resultList := new List<string>;
  var ignoreSpaces := True;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];
    if ch = ' ' then
      continue
    else if ch = '(' then
    begin
      if ignoreSpaces then
        current += ch
      else
      begin
        current += ch;
        stack.Push(current);
        current := '';
      end;
    end
    else if ch = ')' then
    begin
      if ignoreSpaces then
        current += ch
      else
      begin
        current += ch;
        stack.Push(current);
        current := '';
      end;
    end
    else if ch = ',' then
    begin
      if ignoreSpaces then
        current += ch
      else
      begin
        current += ch;
        stack.Push(current);
        current := '';
      end;
    end;
  end;

  while stack.Count > 0 do
  begin
    var group := stack.Pop;
    if ignoreSpaces then
      resultList.Add(group)
    else
      resultList.Add(group.Trim);
  end;

  Result := resultList.ToArray;
end;


