function ParseNestedParens(parenString: string): array of integer;
begin
  var maxDepth := 0;
  var currentDepth := 0;
  var stack := new Stack<integer>;
  var res := new List<integer>;
  var chars := parenString.ToCharArray;

  foreach var c in chars do
  begin
    if c = '(' then
    begin
      currentDepth += 1;
      if currentDepth > maxDepth then
        maxDepth := currentDepth;
      stack.Push(currentDepth);
    end
    else if c = ')' then
    begin
      currentDepth -= 1;
      stack.Pop;
    end;
  end;

  for var i := 0 to maxDepth - 1 do
    res.Add(1);

  Result := res.ToArray;
end;


