end;
function MakePalindrome(str: string): string;
begin
  var postfix := '';
  for var i := str.Length - 1 downto 0 do
  begin
    if IsPalindrome(str.Substring(i)) then
    begin
      postfix := str.Substring(i);
      break;
    end;
  end;

  if postfix = '' then
    Result := str
  else
    Result := str + ReverseString(str.Substring(0, str.Length - postfix.Length));
end;


