  var i := 0;
  while i < str.Length do
  begin
    var j := 0;
    while (i + j < str.Length) and (substring[j] = str[i + j]) do
      j += 1;
    if j = substring.Length then
      count += 1;
    i += j;
  end;
  Result := count;
end;


