function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var factors := new List<integer>;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      n := n div i;
      factors.Add(i);
    end
    else
      i += 1;
  end;
  if n > 1 then
    factors.Add(n);
  Result := factors.ToArray;
end;


