function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs : array of real): real;
{ xs are coefficients of a polynomial.
    FindZero find x such that poly(x) = 0.
    FindZero returns only only zero point, even if there are many.
    Moreover, FindZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(FindZero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(FindZero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0 }
begin
  var n := xs.Length;
  if n mod 2 <> 0 then
    raise new System.ArgumentException('xs must have even number of coefficients');
  var maxCoeff := xs.Max;
  if maxCoeff = 0 then
    raise new System.ArgumentException('xs must have non-zero largest coefficient');
  var (a, b) := (xs[0], xs[1]);
  for var i := 2 to n - 1 step 2 do
  begin
    var c := xs[i];
    var d := xs[i + 1];
    var e := (a + d) / 2;
    var f := Sqrt(Power(e, 2) - 4 * b * c);
    e := (e + f) / 2;
    f := Sqrt(Power(e, 2) - 4 * b * c);
    e := (e - f) / 2;
    a := d;
    b := e;
  end;
  Result := a;
end;


function SortThird(l: array of integer): array of integer;
begin
  var third := new List<integer>;
  var other := new List<integer>;
  var divisible := new List<integer>;

  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
      divisible.Add(l[i])
    else
      other.Add(l[i]);
  end;

  divisible.Sort;

  var j := 0;
  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
      l[i] := divisible[j++]
    else
      l[i] := other[i - j];
  end;

  Result := l;
end;


