function Fib4(n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;

  if n = 1 then
  begin
    Result := 0;
    exit;
  end;

  if n = 2 then
  begin
    Result := 2;
    exit;
  end;

  if n = 3 then
  begin
    Result := 0;
    exit;
  end;

  var fibs := new integer[n + 1];
  fibs[0] := 0;
  fibs[1] := 0;
  fibs[2] := 2;
  fibs[3] := 0;

  for var i := 4 to n do
    fibs[i] := fibs[i - 1] + fibs[i - 2] + fibs[i - 3] + fibs[i - 4];

  Result := fibs[n];
end;


