function CircularShift(x: integer; shift: integer): string;
begin
  var digits := x.ToString.ToCharArray;
  var n := digits.Length;
  shift := shift mod n;
  var shifted := digits[n - shift:n];
  var rotated := digits[0:n - shift];
  Result := string.Join('', rotated) + string.Join('', shifted);
end;


