  var evenIndex := new List<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) then
    begin
      evenList.Add(arr[i]);
      evenIndex.Add(i);
    end;
  end;

  if evenList.Count = 0 then
    Result := new integer[0]
  else
  begin
    var smallestEven := evenList.Min;
    var smallestIndex := evenIndex.IndexOf(evenList.IndexOf(smallestEven));
    Result := |smallestEven, smallestIndex|;
  end;
end;


