  var desc := sorted.OrderByDescending(x -> x).ToArray;
  var res := new List<integer>;

  while desc.Length > 0 do
  begin
    res.Add(desc[0]);
    desc := desc.Skip(1).ToArray;

    if desc.Length > 0 then
    begin
      res.Add(desc[0]);
      desc := desc.Skip(1).ToArray;
