function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;
  var n := 2;
  while n < 100 do
  begin
    var isPrime := True;
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        isPrime := False;
        break;
      end;
    if isPrime then
      primes.Add(n);
    n += 1;
  end;

  var factors := new List<integer>;
  foreach var prime in primes do
  begin
    while a mod prime = 0 do
    begin
      a := a div prime;
      factors.Add(prime);
    end;
  end;

  Result := (a = 1) and (factors.Count = 3);
end;


