function Encode(message: string): string;
begin
  var vowels := new HashSet<char>('aeiouAEIOU'.ToCharArray);
  var sb := new StringBuilder;

  for var i := 1 to message.Length do
  begin
    var c := message[i];
    if c.IsLetter then
    begin
      if c.IsUpper then
        sb.Append(char.ToLower(c))
      else
        sb.Append(char.ToUpper(c));
    end
    else
      sb.Append(c);
  end;

  var encoded := sb.ToString;

  for var i := 1 to encoded.Length - 1 do
  begin
    if vowels.Contains(encoded[i]) and vowels.Contains(encoded[i + 1]) then
    begin
      var index := encoded.IndexOf(encoded[i]);
      var nextIndex := encoded.IndexOf(encoded[i + 1]);
      var chars := encoded.ToCharArray;
      var temp := chars[index];
      chars[index] := chars[nextIndex];
      chars[nextIndex] := temp;
      encoded := new string(chars);
    end;
  end;

  Result := encoded;
end;


