function Exchange(lst1, lst2: array of integer): string;
begin
  var evenCount1 := 0;
  var evenCount2 := 0;
  var oddCount1 := 0;
  var oddCount2 := 0;

  foreach var num in lst1 do
    if num mod 2 = 0 then
      evenCount1 += 1
    else
      oddCount1 += 1;

  foreach var num in lst2 do
    if num mod 2 = 0 then
      evenCount2 += 1
    else
      oddCount2 += 1;

  if (evenCount1 + evenCount2) mod 2 <> 0 then
    Result := 'NO'
  else if (evenCount1 + evenCount2) mod 2 = 0 then
  begin
    if (evenCount1 - oddCount1) mod 2 <> 0 then
      Result := 'NO'
    else if (evenCount1 - oddCount1) mod 2 = 0 then
    begin
      if (evenCount2 - oddCount2) mod 2 <> 0 then
        Result := 'NO'
      else if (evenCount2 - oddCount2) mod 2 = 0 then
        Result := 'YES'
    end;
  end;
end;


