function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var total := 0;
  var res := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        total += 1;

  while total > 0 do
  begin
    var cnt := 0;
    for var i := 0 to m - 1 do
      for var j := 0 to n - 1 do
        if grid[i][j] = 1 then
        begin
          cnt += 1;
          grid[i][j] := 0;
        end;

    if cnt > capacity then
    begin
      res += 1;
      total -= cnt;
    end;
  end;

  Result := res;
end;


