function GetClosestVowel(word: string): string;
begin
  var vowels := new HashSet<char>('aeiouAEIOU'.ToCharArray);
  var vowelStack := new Stack<char>;

  for var i := word.Length - 1 downto 0 do
  begin
    if vowels.Contains(word[i]) then
    begin
      if (vowelStack.Count > 0) and (vowels.Contains(vowelStack.Peek)) then
      begin
        var closestVowel := vowelStack.Pop;
        Result := closestVowel;
        exit;
      end;
      vowelStack.Push(word[i]);
    end;
  end;

  Result := '';
end;


function MatchParens(lst: array of string): string;
