  var stack := new Stack<char>;
  foreach var c in s do
  begin
    if c = '(' then
      stack.Push(c)
    else if c = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := 'No';
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := if stack.Count = 0 then 'Yes' else 'No';
end;


