  begin
    if maxHeapSet.Contains(num) then
      continue;

    maxHeap.Add(num);
    maxHeap.Sort;

    if maxHeap.Count > k then
    begin
      maxHeapSet.Remove(maxHeap[0]);
      maxHeap.RemoveAt(0);
    end;

    maxHeapSet.Add(num);
  end;

  maxHeap.Sort;
  maxHeap.Reverse;
  Result := maxHeap.ToArray;
end;


