  var intersectionEnd := Min(interval1[1], interval2[1]);

  if (intersectionStart > intersectionEnd) or (intersectionEnd - intersectionStart < 2) then
  begin
    Result := 'NO';
    exit;
  end;

  var intersectionLength := intersectionEnd - intersectionStart;
  Result := if IsPrime(intersectionLength) then 'YES' else 'NO';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var product := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    sign := sign * (num > 0) - (num < 0);
    product := product * Abs(num);
    sum := sum + Abs(num);
  end;

  Result := sign * product * sum;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new HashSet<(integer, integer)>;
  var heap := new List<(integer, integer, integer)>;
  heap.Add((grid[0][0], 0, 0));
  var res := new List<integer>;

  while heap.Count > 0 do
  begin
    heap.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (val, x, y) := heap[0];
    heap.RemoveAt(0);

    if res.Count = k then
    begin
      Result := res.ToArray;
      exit;
    end;

    if visited.Contains((x, y)) then
      continue;

    visited.Add((x, y));
    res.Add(val);

    for var i := 0 to 3 do
    begin
      var (dx, dy) := directions[i];
      var nx := x + dx;
      var ny := y + dy;

      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited.Contains((nx, ny)) then
        heap.Add((grid[nx][ny], nx, ny));
    end;
  end;

  Result := new integer[0];
end;


function Tri(n: integer): array of real;
begin
  var tri := new real[n + 1];
  tri[0] := 3;
  if n > 0 then
    tri[1] := 1;
  if n > 1 then
    tri[2] := 2;
  for var i := 3 to n do
    tri[i] := tri[i - 1] + tri[i - 2] + tri[i - 3];
  Result := tri;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      product *= digit;
      hasOdd := True;
    end;
    n := n div 10;
  end;
  Result := if hasOdd then product else 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


