      aStr := aStr.Substring(0, aStr.Length - 1);
    if bStr.EndsWith(',') then
      bStr := bStr.Substring(0, bStr.Length - 1);
    if aStr.ToFloat < bStr.ToFloat then
      Result := a
    else if aStr = bStr then
      Result := nil
    else
      Result := b;
  end
  else if a is real then
  begin
    var aReal := a as real;
    var bReal := b as real;
    if aReal < bReal then
      Result := a
    else if aReal = bReal then
      Result := nil
    else
      Result := b;
  end
  else if a is integer then
  begin
    var aInt := a as integer;
    var bInt := b as integer;
    if aInt < bInt then
      Result := a
    else if aInt = bInt then
      Result := nil
    else
      Result := b;
  end
  else
    Result := nil;
end;


