function IntToMiniRoman(number: integer): string;
begin
  if number = 0 then
  begin
    Result := '';
    exit;
  end;

  var roman := new Dictionary<integer, string>;
  roman[1000] := 'm';
  roman[900] := 'cm';
  roman[500] := 'd';
  roman[400] := 'cd';
  roman[100] := 'c';
  roman[90] := 'xc';
  roman[50] := 'l';
  roman[40] := 'xl';
  roman[10] := 'x';
  roman[9] := 'ix';
  roman[5] := 'v';
  roman[4] := 'iv';
  roman[1] := 'i';

  var resultStr := '';
  var num := number;

  while num > 0 do
  begin
    foreach var k in roman.Keys do
    begin
      while num >= k do
      begin
        resultStr += roman[k];
        num -= k;
      end;
    end;
  end;

  Result := resultStr;
end;


