    if uniqueChars.Count > maxUnique then
    begin
      maxUnique := uniqueChars.Count;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
  begin
    Result := (number + need, remaining - need);
  end
  else
  begin
    Result := (number + remaining, 0);
  end;
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    if op[i - 1] = '+' then
      res += operand[i]
    else if op[i - 1] = '-' then
      res -= operand[i]
    else if op[i - 1] = '*' then
      res *= operand[i]
    else if op[i - 1] = '//' then
      res := integer(res div operand[i])
    else if op[i - 1] = '**' then
      res := integer(Power(res, operand[i]))
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var isLetter := false;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if Char.IsLetter(c) then
    begin
      isLetter := true;
      if Char.IsLower(c) then
        sb.Append(Char.ToUpper(c))
      else
        sb.Append(Char.ToLower(c));
    end
    else
    begin
      isLetter := false;
      if sb.Length > 0 then
        sb.Append(c);
    end;
  end;

  if isLetter then
    Result := sb.ToString
  else
    Result := sb.ToString.ToUpper;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);
  var sb := new System.Text.StringBuilder;

  for var i := 0 to hash.Length - 1 do
    sb.Append(hash[i].ToString('x2'));

  Result := sb.ToString;
end;


